using System;using System.Drawing;using System.Reflection;
class CastBodyConsistencyChecks {
 static void Main(){using(var c=new PartyBattleCanvas()){c.MaleIdle=new[]{HeroIdleAnimation.Load("D:/WORK/Cet6Story/assets/characters/animations/luchuan-idle.gif")[0]};c.MaleActions=Image.FromFile("D:/WORK/Cet6Story/assets/characters/actions/luchuan-actions-v2.png");var hero=new PartyUnit{id="luchuan"};foreach(var skill in new[]{"bolt","inscribe","screen"}){c.PlayCast("luchuan",skill,"enemy-0",true,null);((System.Windows.Forms.Timer)typeof(PartyBattleCanvas).GetField("castTimer",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(c)).Stop();System.Threading.Thread.Sleep(960);using(var actual=new Bitmap(800,600))using(var expected=new Bitmap(800,600))using(var g=Graphics.FromImage(actual))using(var e=Graphics.FromImage(expected)){var args=new object[]{g,hero,300f,500,240f,Rectangle.Empty};typeof(PartyBattleCanvas).GetMethod("DrawCastHero",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(c,args);var bounds=(Rectangle)args[5];var image=c.MaleIdle[0];float h=240f*468/395f,w=h*image.Width/image.Height;var idle=new Rectangle((int)(300-w/2),(int)(500+240f*50/395f-h),(int)w,(int)h);if(bounds!=idle)throw new Exception("idle anchor differs: "+skill);e.DrawImage(image,idle);int changed=0;for(int y=0;y<600;y++)for(int x=0;x<800;x++){bool fixedBody=y<idle.Y+idle.Height*.26f||y>idle.Y+idle.Height*.62f;if(actual.GetPixel(x,y)!=expected.GetPixel(x,y)){if(fixedBody)throw new Exception("head or legs differ: "+skill);changed++;}}if(changed<100)throw new Exception("casting arms did not move: "+skill);}}c.MaleActions.Dispose();}Console.WriteLine("PASS: attack, chant and shield casting head/legs, dimensions and foot anchor equal idle; arms animate");}
}

